// swap two values reversibly (C-style)
void swap(int a, int b) {
    a ^= b;
    b ^= a;
    a ^= b;
}
void main() {
    int x = 7;
    int y = 11;
    printf("before: x=%d y=%d\n", x, y);
    call swap(x, y);
    printf("after:  x=%d y=%d\n", x, y);
}

